function makeEnemy(index){
 const group=new THREE.Group();const armorMat=mat(index%2?'#7b3730':'#963d32',.42,.42), dark=mat('#202522',.5,.4), visor=mat('#ff806a',.25,.25,{emissive:'#c33b29',emissiveIntensity:1.6});
