import {readFileSync} from 'node:fs';
const require=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
const browser=await chromium.launch({...config.browser.launchOptions,headless:true});
const errors=[];
const page=await browser.newPage({viewport:{width:1440,height:900}});
page.on('pageerror',e=>errors.push(e.message));
page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text());});
await page.goto('http://127.0.0.1:3000');
await page.waitForTimeout(500);
await page.locator('.mode-card').nth(3).click();
await page.waitForTimeout(300);
console.log('desktop started mode:',await page.locator('#hudMode').textContent(),'exit visible:',await page.locator('#exitBtn').isVisible());
await page.locator('#exitBtn').click({timeout:3000});
console.log('exit button returns to lobby:',await page.locator('#lobby').isVisible());
await page.locator('.mode-card').nth(3).click();
await page.keyboard.down('w');
for(let i=0;i<35;i++){
 await page.waitForTimeout(1000);
 const health=Number(await page.locator('#healthNum').textContent());
 if(i%5===4)console.log('health after',i+1,'s:',health,'death visible:',await page.locator('#deathOverlay').isVisible());
}
await page.keyboard.up('w');
console.log('desktop errors:',errors);
await page.screenshot({path:'screenshots/gameplay-desktop.png'});
await browser.close();
EOF

